using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;
using UnityEngine;
namespace CampaignDemo {
 public static class BattleReplayExporter {
  static string F(float value){return value.ToString("0.####",CultureInfo.InvariantCulture);}
  static string Esc(string text){return System.Security.SecurityElement.Escape(text??"");}
  static string J(string text){return "\""+(text??"").Replace("\\","\\\\").Replace("\"","\\\"").Replace("\n","\\n").Replace("\r","\\r")+"\"";}
  public static string Export(BattleReplayRecorder recorder){if(recorder==null||!recorder.Finished)throw new InvalidOperationException("作战尚未结束");string directory=recorder.exportDirectory;
   if(string.IsNullOrEmpty(directory)){
    #if UNITY_EDITOR
    directory=System.IO.Path.GetFullPath(System.IO.Path.Combine(Application.dataPath,"../BattleReports"));
    #else
    directory=System.IO.Path.Combine(Application.persistentDataPath,"BattleReports");
    #endif
   }Directory.CreateDirectory(directory);string name="作战复盘-"+DateTime.Now.ToString("yyyyMMdd-HHmmss-fff");string prefix=System.IO.Path.Combine(directory,name);
   var camera=recorder.world.setup.mapCamera;var presentation=recorder.GetComponent<BattleReplayPresentation>();var bounds=recorder.Snapshot.bounds;
   var position=camera.transform.position;var rotation=camera.transform.rotation;float zoom=camera.orthographicSize;var rect=camera.rect;var oldTarget=camera.targetTexture;var active=RenderTexture.active;
   int width=2048,height=Mathf.Clamp(Mathf.RoundToInt(width*bounds.height/bounds.width),256,4096);var rt=new RenderTexture(width,height,24);var tex=new Texture2D(width,height,TextureFormat.RGB24,false);byte[] background;
   try{rt.Create();camera.targetTexture=rt;camera.rect=new Rect(0,0,1,1);camera.transform.position=new Vector3(bounds.center.x,bounds.center.y,position.z);camera.transform.rotation=Quaternion.identity;camera.orthographicSize=bounds.height/2;presentation.Root.gameObject.SetActive(false);camera.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();background=tex.EncodeToPNG();presentation.Root.gameObject.SetActive(true);presentation.RefreshMarkerSizes();camera.Render();tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();File.WriteAllBytes(prefix+".png",tex.EncodeToPNG());}
   finally{presentation.Root.gameObject.SetActive(true);camera.targetTexture=oldTarget;camera.rect=rect;camera.transform.position=position;camera.transform.rotation=rotation;camera.orthographicSize=zoom;presentation.RefreshMarkerSizes();RenderTexture.active=active;rt.Release();UnityEngine.Object.Destroy(rt);UnityEngine.Object.Destroy(tex);}
   File.WriteAllText(prefix+".svg",Svg(recorder,width,height,background),new UTF8Encoding(false));File.WriteAllText(prefix+".json",Json(recorder.Snapshot),new UTF8Encoding(false));recorder.LastExport=prefix;return prefix;
  }
  static byte[] Symbol(Sprite sprite){
   #if UNITY_EDITOR
   string file=UnityEditor.AssetDatabase.GetAssetPath(sprite);if(File.Exists(file))return File.ReadAllBytes(file);
   #endif
   var rt=RenderTexture.GetTemporary(sprite.texture.width,sprite.texture.height,0,RenderTextureFormat.ARGB32);var old=RenderTexture.active;var texture=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);try{Graphics.Blit(sprite.texture,rt);RenderTexture.active=rt;texture.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);texture.Apply();return texture.EncodeToPNG();}finally{RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.Destroy(texture);}
  }
  public static string Svg(BattleReplayRecorder recorder,int width,int height,byte[] background){var snapshot=recorder.Snapshot;var b=snapshot.bounds;float scale=width/b.width;const int top=76;var s=new StringBuilder();
   s.Append("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"").Append(width).Append("\" height=\"").Append(height+top+100).Append("\" viewBox=\"0 0 ").Append(width).Append(' ').Append(height+top+100).Append("\"><defs>");
   s.Append("<pattern id=\"blueHatch\" width=\"22\" height=\"22\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\"><path d=\"M0 0 V22\" stroke=\"#1438D1\" stroke-width=\"3\"/></pattern><pattern id=\"redHatch\" width=\"22\" height=\"22\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(-45)\"><path d=\"M0 0 V22\" stroke=\"#D11438\" stroke-width=\"3\"/></pattern>");
   for(int side=0;side<2;side++){string id=side==0?"blue":"red";s.Append("<marker id=\"").Append(id).Append("Arrow\" markerWidth=\"8\" markerHeight=\"8\" refX=\"4\" refY=\"2\" orient=\"auto\" markerUnits=\"strokeWidth\"><path d=\"M0 0 L4 2 L0 4 Z\" fill=\"").Append(side==0?"#1438D1":"#D11438").Append("\"/></marker><clipPath id=\"").Append(id).Append("Observation\">");
    foreach(var army in snapshot.armies)if((army.owner==snapshot.blueOwner)==(side==0))foreach(var trail in army.observation){if(trail.points.Count==0)continue;if(trail.points.Count==1){var p=Map(trail.points[0],b,scale,top);s.Append("<circle cx=\"").Append(F(p.x)).Append("\" cy=\"").Append(F(p.y)).Append("\" r=\"").Append(F(trail.radius*scale)).Append("\"/>");}else{
      // Filled swept-circle outlines work in clipPath; strokes alone are not a clip geometry.
      s.Append("<path d=\"").Append(CapsuleUnion(trail,b,scale,top)).Append("\"/>");
    }}s.Append("</clipPath>");}
   s.Append("</defs><rect width=\"100%\" height=\"100%\" fill=\"#eeeae0\"/><text x=\"28\" y=\"34\" font-family=\"Microsoft YaHei,sans-serif\" font-size=\"26\">陆军战术手册 · 静态作战复盘</text><text x=\"28\" y=\"61\" font-family=\"Microsoft YaHei,sans-serif\" font-size=\"15\">战斗时长 ").Append(F(snapshot.elapsed)).Append(" 秒；观察区截止 T/4 = ").Append(F(snapshot.observationCutoff)+" 秒").Append("</text><image x=\"0\" y=\"").Append(top).Append("\" width=\"").Append(width).Append("\" height=\"").Append(height).Append("\" href=\"data:image/png;base64,").Append(Convert.ToBase64String(background)).Append("\"/>");
   foreach(string side in new[]{"blue","red"})s.Append("<rect x=\"0\" y=\"").Append(top).Append("\" width=\"").Append(width).Append("\" height=\"").Append(height).Append("\" fill=\"url(#").Append(side).Append("Hatch)\" opacity=\".5\" clip-path=\"url(#").Append(side).Append("Observation)\"/>");
   if(recorder.GetComponent<BattleReplayPresentation>().ShowTactical){var settings=recorder.world.setup.settings;float units=b.width/width;foreach(var army in snapshot.armies)foreach(var route in army.tacticalRoutes){if(route.Count<2)continue;var points=new List<RoadPoint>();foreach(var p in route)points.Add(new RoadPoint(p.x,p.y));var contour=RoadRouteView.ArrowContour(points,Mathf.Max(settings.arrowShaftWidth,units*settings.minimumArrowShaftPixels),Mathf.Max(settings.arrowHeadWidth,units*settings.minimumArrowHeadPixels),Mathf.Max(settings.arrowHeadLength,units*settings.minimumArrowHeadLengthPixels),(route[route.Count-1]-army.finalPosition).sqrMagnitude<.00000001f);if(contour.Count==0)continue;s.Append("<path data-army=\"").Append(Esc(army.id)).Append("\" d=\"M");for(int i=0;i<contour.Count;i++){var p=Map(contour[i],b,scale,top);if(i>0)s.Append(" L");s.Append(F(p.x)).Append(' ').Append(F(p.y));}if(!settings.arrowOpenTail)s.Append(" Z");s.Append("\" fill=\"none\" stroke=\"").Append(army.owner==snapshot.blueOwner?"#1459B3":"#D11438").Append("\" stroke-width=\"").Append(F(Mathf.Max(settings.arrowStrokeWidth*scale,settings.minimumArrowStrokePixels))).Append("\"/>");}}
   foreach(var defense in snapshot.defenses){string color=defense.owner==snapshot.blueOwner?"#1438D1":"#D11438";s.Append("<path d=\"").Append(Path(defense.points,b,scale,top)).Append("\" fill=\"none\" stroke=\"").Append(color).Append("\" stroke-width=\"4\" stroke-linejoin=\"round\"");if(defense.destroyed)s.Append(" stroke-dasharray=\"7 5\" opacity=\".55\"");s.Append("/>");for(int i=1;i<defense.points.Length;i++){var a=Map(defense.points[i-1],b,scale,top);var end=Map(defense.points[i],b,scale,top);var d=end-a;float length=d.magnitude;var n=new Vector2(-d.y,d.x).normalized*8;for(float t=20;t<length;t+=24){var p=a+d/length*t;s.Append("<path d=\"M").Append(F(p.x)).Append(' ').Append(F(p.y)).Append(" l").Append(F(n.x)).Append(' ').Append(F(n.y)).Append("\" stroke=\"").Append(color).Append("\" stroke-width=\"2\"/>");}}}
   foreach(var army in snapshot.armies){var p=Map(army.displayPosition,b,scale,top);var real=Map(army.finalPosition,b,scale,top);if(Vector2.Distance(real,p)>.01f)s.Append("<path d=\"M").Append(F(real.x)).Append(' ').Append(F(real.y)).Append(" L").Append(F(p.x)).Append(' ').Append(F(p.y)).Append("\" stroke=\"#222\" opacity=\".65\" stroke-width=\"1\"/>");if(army.symbol!=null){float w=army.owner==snapshot.blueOwner?36:48,h=w*army.symbol.rect.height/army.symbol.rect.width;s.Append("<image x=\"").Append(F(p.x-w*army.symbol.pivot.x/army.symbol.rect.width)).Append("\" y=\"").Append(F(p.y-h*(1-army.symbol.pivot.y/army.symbol.rect.height))).Append("\" width=\"").Append(F(w)).Append("\" height=\"").Append(F(h)).Append("\" style=\"image-rendering:pixelated\" href=\"data:image/png;base64,").Append(Convert.ToBase64String(Symbol(army.symbol))).Append("\"/>");}
    s.Append("<text x=\"").Append(F(p.x+26)).Append("\" y=\"").Append(F(p.y+12)).Append("\" font-family=\"Microsoft YaHei,sans-serif\" font-size=\"12\" fill=\"#151515\" paint-order=\"stroke\" stroke=\"#eeeae0\" stroke-width=\"3\">").Append(Esc(army.label)).Append("</text>");if(army.dead)s.Append("<path d=\"M").Append(F(p.x-(army.owner==snapshot.blueOwner?18:24)-18)).Append(' ').Append(F(p.y-7)).Append(" l14 14 m-14 0 l14 -14\" stroke=\"#000\" stroke-width=\"3\"/>");}
   s.Append("<text x=\"28\" y=\"").Append(height+top+34).Append("\" font-family=\"Microsoft YaHei,sans-serif\" font-size=\"14\">斜纹：前四分之一时间的累计圆形视野；红蓝空心战术箭头（对应阵营）：整场战斗的实际行进路径（明显重叠处已去重）；带短划线：防线；×：军队死亡</text><text x=\"28\" y=\"").Append(height+top+65).Append("\" font-family=\"Microsoft YaHei,sans-serif\" font-size=\"14\">双方使用相同记录规则；军标位于死亡位置或结束位置。军标固定于真实位置；只有到达该单位终点的路径片段显示箭头尖端。参考 FM 1-02.2 图形类别，复盘含义为游戏约定。</text></svg>");   float bar=Mathf.Min(200, width*.1f);float distance=bar/scale*snapshot.metersPerWorldUnit;float nice=Mathf.Pow(10,Mathf.Floor(Mathf.Log10(Mathf.Max(.01f,distance))));nice*=distance/nice>=5?5:distance/nice>=2?2:1;bar=nice/snapshot.metersPerWorldUnit*scale;int insert=s.ToString().LastIndexOf("</svg>");s.Insert(insert,"<path d=\"M"+F(width-250)+" "+F(height+top+86)+" h"+F(bar)+"\" stroke=\"#111\" stroke-width=\"4\"/><text x=\""+F(width-250)+"\" y=\""+F(height+top+78)+"\" font-family=\"Microsoft YaHei,sans-serif\" font-size=\"14\">"+(nice>=1000?F(nice/1000)+" km":F(nice)+" m")+"</text>");return s.ToString();
  }
  static List<Vector3> Trim(IList<Vector3> path,float gap){var result=new List<Vector3>(path);float length=0;for(int i=1;i<path.Count;i++)length+=Vector3.Distance(path[i-1],path[i]);gap=Mathf.Min(gap,length*.3f);while(result.Count>1&&gap>0){int n=result.Count;float leg=Vector3.Distance(result[n-1],result[n-2]);if(leg<=gap){gap-=leg;result.RemoveAt(n-1);}else{result[n-1]=Vector3.MoveTowards(result[n-1],result[n-2],gap);break;}}return result;}
  static Vector2 Map(Vector3 p,Rect b,float scale,int top){return new Vector2((p.x-b.xMin)*scale,(b.yMax-p.y)*scale+top);}
  static string Path(IList<Vector3> points,Rect b,float scale,int top){if(points.Count==0)return "";var s=new StringBuilder();var a=Map(points[0],b,scale,top);s.Append('M').Append(F(a.x)).Append(' ').Append(F(a.y));for(int i=1;i<points.Count;i++){var p=Map(points[i],b,scale,top);if(i<points.Count-1){var next=Map(points[i+1],b,scale,top);float r=Mathf.Min(8,Mathf.Min(Vector2.Distance(a,p),Vector2.Distance(p,next))*.25f);var enter=Vector2.MoveTowards(p,a,r);var exit=Vector2.MoveTowards(p,next,r);s.Append(" L").Append(F(enter.x)).Append(' ').Append(F(enter.y)).Append(" Q").Append(F(p.x)).Append(' ').Append(F(p.y)).Append(' ').Append(F(exit.x)).Append(' ').Append(F(exit.y));a=exit;}else s.Append(" L").Append(F(p.x)).Append(' ').Append(F(p.y));}return s.ToString();}
  static string CapsuleUnion(ReplayVisionTrail trail,Rect b,float scale,int top){var s=new StringBuilder();float radius=trail.radius*scale;
   foreach(var point in trail.points){var p=Map(point,b,scale,top);s.Append('M').Append(F(p.x-radius)).Append(' ').Append(F(p.y)).Append(" a").Append(F(radius)).Append(' ').Append(F(radius)).Append(" 0 1 0 ").Append(F(2*radius)).Append(" 0 a").Append(F(radius)).Append(' ').Append(F(radius)).Append(" 0 1 0 ").Append(F(-2*radius)).Append(" 0 Z ");}
   for(int i=1;i<trail.points.Count;i++){var a=Map(trail.points[i-1],b,scale,top);var c=Map(trail.points[i],b,scale,top);var d=c-a;var normal=new Vector2(-d.y,d.x).normalized*radius;foreach(var p in new[]{a+normal,c+normal,c-normal,a-normal})s.Append(p==a+normal?'M':'L').Append(F(p.x)).Append(' ').Append(F(p.y)).Append(' ');s.Append("Z ");}return s.ToString();
  }
  static string Json(ReplaySnapshot snap){var s=new StringBuilder("{\"version\":1,\"elapsed\":");s.Append(F(snap.elapsed)).Append(",\"bounds\":[").Append(F(snap.bounds.x)).Append(',').Append(F(snap.bounds.y)).Append(',').Append(F(snap.bounds.width)).Append(',').Append(F(snap.bounds.height)).Append("],\"metersPerWorldUnit\":").Append(F(snap.metersPerWorldUnit)).Append(",\"observationCutoff\":").Append(F(snap.observationCutoff)).Append(",\"firstContact\":").Append(F(snap.firstContact)).Append(",\"blueOwner\":").Append(J(snap.blueOwner)).Append(",\"armies\":[");for(int i=0;i<snap.armies.Count;i++){if(i>0)s.Append(',');var a=snap.armies[i];s.Append("{\"id\":").Append(J(a.id)).Append(",\"owner\":").Append(J(a.owner)).Append(",\"label\":").Append(J(a.label)).Append(",\"role\":").Append(J(a.role.ToString())).Append(",\"echelon\":").Append(J(a.echelon.ToString())).Append(",\"dead\":").Append(a.dead?"true":"false").Append(",\"deathTime\":").Append(F(a.deathTime)).Append(",\"finalPosition\":");Point(s,a.finalPosition);s.Append(",\"hasSummaryStart\":").Append(a.hasSummaryStart?"true":"false").Append(",\"summaryStart\":");Point(s,a.summaryStart);s.Append(",\"displayPosition\":");Point(s,a.displayPosition);s.Append(",\"routes\":[");for(int j=0;j<a.routes.Count;j++){if(j>0)s.Append(',');Points(s,a.routes[j]);}s.Append("],\"tacticalMovement\":[");for(int j=0;j<a.tacticalRoutes.Count;j++){if(j>0)s.Append(',');Points(s,a.tacticalRoutes[j]);}s.Append("],\"fullMovement\":[");for(int j=0;j<a.fullRoutes.Count;j++){if(j>0)s.Append(',');Points(s,a.fullRoutes[j]);}s.Append("],\"precontactObservation\":[");for(int j=0;j<a.observation.Count;j++){if(j>0)s.Append(',');var t=a.observation[j];s.Append("{\"radius\":").Append(F(t.radius)).Append(",\"points\":");Points(s,t.points);s.Append('}');}s.Append("]}");}s.Append("],\"defenses\":[");for(int i=0;i<snap.defenses.Count;i++){if(i>0)s.Append(',');var f=snap.defenses[i];s.Append("{\"owner\":").Append(J(f.owner)).Append(",\"destroyed\":").Append(f.destroyed?"true":"false").Append(",\"points\":");Points(s,f.points);s.Append('}');}return s.Append("]}").ToString();}
  static void Points(StringBuilder s,IList<Vector3> points){s.Append('[');for(int i=0;i<points.Count;i++){if(i>0)s.Append(',');Point(s,points[i]);}s.Append(']');}
  static void Point(StringBuilder s,Vector3 p){s.Append('[').Append(F(p.x)).Append(',').Append(F(p.y)).Append(']');}
 }
